//! Rust-own goldens: outputs of the Rust sim itself, compared BIT FOR BIT (floats are written as their IEEE bits) so a platform
//! that changes any result by one ulp fails. They are separate from the C++ oracle goldens in `tests/golden/`, which are judged
//! within a stated tolerance. The files in `tests/rust_golden/` are generated by the Rust sim on aarch64 macOS with
//!
//! ```text
//! MC2_REGEN_RUST_GOLDEN=1 MC2_DATA=<gamedata/mc2exe> cargo test -p mc2-sim --test terrain --test mover_replay --test appearance_replay
//! ```
//!
//! and are checked unchanged on aarch64 macOS and x86_64 (see the porting log, "Cross-platform determinism").
#![allow(dead_code)]

use std::path::PathBuf;

pub fn path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/rust_golden")
        .join(name)
}

/// Compare `text` with the committed file `name` byte for byte, or (with `MC2_REGEN_RUST_GOLDEN` set) rewrite it.
pub fn check(name: &str, text: &str) {
    let p = path(name);
    if std::env::var_os("MC2_REGEN_RUST_GOLDEN").is_some() {
        std::fs::write(&p, text).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
        return;
    }
    let want = std::fs::read_to_string(&p).unwrap_or_else(|e| {
        panic!(
            "{}: {e} (generate with MC2_REGEN_RUST_GOLDEN=1)",
            p.display()
        )
    });
    if want == text {
        return;
    }
    for (i, (a, b)) in want.lines().zip(text.lines()).enumerate() {
        assert_eq!(
            a,
            b,
            "{name}: first differing line {} (rust-own golden, bit-exact)",
            i + 1
        );
    }
    panic!(
        "{name}: line count {} vs {}",
        want.lines().count(),
        text.lines().count()
    );
}

/// `f32` as `hex bits`, the form every Rust-own golden uses.
pub fn b(v: f32) -> String {
    format!("{:08x}", v.to_bits())
}
